/** Runs every step in order. */
export async function runFlow(page: Page, vars: Vars): Promise<Outputs> {
  const outputs: Outputs = {};
  await page.goto('http://127.0.0.1:4180/');
  await steps['01-open'](page, { v2: 'http://127.0.0.1:4180/', v3: 'bench@example.com', v4: 'bench-pass-1234', v5: `${vars.runid} RD Bench Ticket` }, outputs);
  await steps['02-add'](page, { d1: '', v1: `${vars.runid} RD Bench Ticket`, v3: outputs['01-open.ticket_reference'] ?? '', v4: `${vars.runid} RD Part A`, v5: '100', v6: '25' }, outputs);
  await steps['03-add'](page, { v1: `${vars.runid} RD Bench Ticket`, v3: outputs['01-open.ticket_reference'] ?? '', v4: `${vars.runid} RD Part A`, v5: `${vars.runid} RD Part B`, v6: '200', v7: '25' }, outputs);
  await steps['04-edit'](page, { v1: `${vars.runid} RD Bench Ticket`, v3: outputs['01-open.ticket_reference'] ?? '', v4: `${vars.runid} RD Part A`, v5: '150' }, outputs);
  await steps['05-change'](page, { v1: `${vars.runid} RD Bench Ticket`, v2: vars.runid, v3: outputs['01-open.ticket_reference'] ?? '' }, outputs);
  await steps['06-report'](page, { v1: `${vars.runid} RD Bench Ticket`, v3: outputs['01-open.ticket_reference'] ?? '', v4: `${vars.runid} RD Part A`, v5: `${vars.runid} RD Part B` }, outputs);
  await steps['07-verify'](page, { v1: `${vars.runid} RD Bench Ticket`, v3: outputs['01-open.ticket_reference'] ?? '' }, outputs);
  return outputs;
}
